class Node:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next
def from_list(values):
    head = None
    for v in reversed(values):
        head = Node(v, head)
    return head
def to_list(head):
    out = []
    while head:
        out.append(head.value)
        head = head.next
    return out
def reverse(head):
    prev = None
    curr = head
    while curr != None:
        next_node = curr.next
        curr.next = prev
        prev = curr
        curr = next_node
    return prev
def remove_all(head, value):
    dummy = Node(0)
    dummy.next = head
    curr = dummy
    while curr.next != None:
        if curr.next.value == value:
            curr.next = curr.next.next
        else:
            curr = curr.next
    return dummy.next
def middle(head):
    if head == None:
        return None
    slow = head
    fast = head
    while fast != None and fast.next != None:
        slow = slow.next
        fast = fast.next.next
    return slow.value
print(to_list(reverse(from_list([1, 2, 3]))))

